// Good: each variant is explicit
interface ButtonProps {
  variant: 'primary' | 'secondary' | 'danger';
  size: 'sm' | 'md' | 'lg';
  disabled?: boolean;
}

function Button({
  variant,
  size,
  disabled = false
}: ButtonProps) {
  return (
    <button
      className={cn(styles[variant], styles[size])}
      disabled={disabled}
    >
      Click me
    </button>
  );
}

type AsProp<
  C extends React.ElementType
> = {
  as?: C;
};

type PropsToOmit<
  C extends React.ElementType,
  P extends object
> = keyof (AsProp<C> & P);

type BoxProps<
  C extends React.ElementType = 'div'
> = React.ComponentPropsWithoutRef<C> &
  AsProp<C> & {
    padding?: string;
    margin?: string;
  };

function Box<C extends React.ElementType = 'div'>({
  as,
  padding,
  margin,
  ...props
}: BoxProps<C>) {
  const Component = as || 'div';
  return (
    <Component
      {...props}
      style={{ padding, margin }}
    />
  );
}

// Usage preserves HTML attributes for each element
<Box as='a' href='https://example.com'>Link</Box>
<Box as='button' onClick={handleClick}>Click</Box>

interface TabsContextValue {
  activeIndex: number;
  setActiveIndex: (index: number) => void;
}

const TabsContext = React.createContext<TabsContextValue | undefined>(undefined);

function Tabs({ children }: { children: React.ReactNode }) {
  const [activeIndex, setActiveIndex] = useState(0);
  return (
    <TabsContext.Provider value={{ activeIndex, setActiveIndex }}>
      <div className='tabs'>{children}</div>
    </TabsContext.Provider>
  );
n}

function TabList({ children }: { children: React.ReactNode }) {
  return <div role='tablist'>{children}</div>;
}

function Tab({
  index,
  children
}: {
  index: number;
  children: React.ReactNode;
}) {
  const context = React.useContext(TabsContext);
  if (!context) throw new Error('Tab must be used inside Tabs');

  return (
    <button
      role='tab'
      aria-selected={context.activeIndex === index}
      onClick={() => context.setActiveIndex(index)}
    >
      {children}
    </button>
  );
}

// Usage
<Tabs>
  <TabList>
    <Tab index={0}>Profile</Tab>
    <Tab index={1}>Settings</Tab>
  </TabList>
</Tabs>
